+                name: "Slow".into(),
+                arguments: "{}".into(),
+            },
+            ToolCall {
+                id: "fast".into(),
+                name: "Fast".into(),
+                arguments: "{}".into(),
+            },
+            ToolCall {
+                id: "queued".into(),
+                name: "Queued".into(),
+                arguments: "{}".into(),
+            },
+            ToolCall {
+                id: "unstarted".into(),
+                name: "Unstarted".into(),
+                arguments: "{}".into(),
+            },
+        ];
+
+        let started = Instant::now();
+        let results = execute_tools(&calls, &exec, 2, Duration::from_millis(100)).await;
